TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"partial","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":"Question 3; References"}],"technical_issues":[{"where":"Question 1","issue":"900 orders per hour is 15 orders per minute on average, not about 150 per minute."},{"where":"Question 1","issue":"The availability response measure, “stay up most of the time,” is not measurable."},{"where":"Question 3","issue":"The downtime arithmetic in part (b) is incorrect: the displayed availability yields about 5.0 hours per 30-day month."},{"where":"Question 3","issue":"Part (c) uses payment-pair availability as end-to-end availability. Multiplying by the other components gives approximately 99.80% availability and 1.5 hours of monthly downtime."},{"where":"Question 4","issue":"Circuit-breaker states are reversed: Closed normally permits calls; failures open the breaker; successful half-open probes close it."},{"where":"Question 5","issue":"CAP does not permit choosing consistency and availability while giving up partition tolerance; during a partition a system must trade off consistency and availability."},{"where":"Question 6","issue":"Retrying queue delivery can produce duplicate notifications; idempotent consumption is a relevant consideration."}],"overall":"24/40. The architectural recommendation is well matched to the scenario, but availability calculations, the circuit-breaker state explanation, and CAP reasoning need correction. The availability scenario is not measurable, and communication loses credit for an overlength answer and an incomplete reference list.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Both attributes are relevant and justified using the lunch peak and current response time. The performance scenario has a measurable response measure, but the availability measure is not measurable and its response does not clearly address order placement.","evidence":[{"where":"Question 1","quote":"The two most important quality attributes are performance and availability"},{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"Clearly recommends a modular monolith and supports it with scenario-specific trade-offs involving the five-person team, single-VM load issue, and deployment downtime. It also acknowledges the reduced independent scalability and shared-process failure risk.","evidence":[{"where":"Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Developing","mark":3.0,"scale":8.0,"points":3.0,"max":8.0,"reasoning":"Part (a) uses the correct series method and gives 99.30%. Part (b) has an arithmetic error: downtime is about 5.0 hours. Part (c) reports provider-pair availability rather than end-to-end availability; including the other components gives about 99.80% and 1.5 hours of monthly downtime.","evidence":[{"where":"Question 3","quote":"A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"},{"where":"Question 3","quote":"Downtime = (1 − 0.99301) × 720 = 0.00699 × 720 = 3.5 hours per month."},{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%"}]},{"id":"C4","level":"Developing","mark":2.0,"scale":5.0,"points":2.0,"max":5.0,"reasoning":"The circuit breaker is appropriate and the fail-fast containment idea is relevant, but the Closed/Open transitions are reversed, as are the stated recovery transitions. No drawback or tuning consideration is given. The threshold example does show some tuning awareness, so this earns partial credit.","evidence":[{"where":"Question 4","quote":"In the Open state calls pass through normally."},{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Closed"}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"The menu choice is justified and names a cache with a TTL. Consistency is a reasonable priority for payment, but the CAP explanation is incorrect and no concrete consistency technique is given for payment processing.","evidence":[{"where":"Question 5","quote":"I would favour availability."},{"where":"Question 5","quote":"for payments we choose consistency and availability and give up partition tolerance."}]},{"id":"C6","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Context, Decision, and Consequences are present and scenario-specific. The consequences describe benefits only; no negative consequence, such as duplicate delivery or added operational complexity, is acknowledged.","evidence":[{"where":"Question 6","quote":"Decision: Publish an \"OrderPaid\" event to a durable message queue (RabbitMQ)."},{"where":"Question 6","quote":"Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"The headings and writing are clear, but Question 2 exceeds the 150-word limit. Numeric citations are used, but citation [2] has no corresponding reference-list entry.","evidence":[{"where":"Question 2","quote":"I recommend against a full microservices rewrite for the next 12 months."},{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."},{"where":"References","quote":"[1] L. Bass, P. Clements, and R. Kazman"}]}]}
